import styled from "styled-components";

export const PaginationContainer= styled.div`
    width:120px;
    display: flex;
    align-items: center;
    justify-content: center;

    .pagination-box{
        width: 100%;
        display: flex;
        align-items: center;
        justify-content: center;


    }
`
